const normal=value=>String(value||'').toLocaleLowerCase('en').trim().replace(/^to\s+/,'').replace(/\s+/g,' ');
let byEnglish;
function get(card){
 const key=normal(card.en);
 let entry=DATA.pdf[card.id];
 if(!entry)entry=DATA.native[key];
 if(!entry){
  if(!byEnglish){
   byEnglish=new Map();
   for(const c of window.ENGLISH_CONTENT?.vocab||[]){const r=DATA.pdf[c.id];if(r&&!byEnglish.has(normal(c.en)))byEnglish.set(normal(c.en),r)}
  }
  entry=byEnglish.get(key);
 }
 const safe=entry||{};
 return {synonyms:[...(safe.synonyms||[])],antonyms:[...(safe.antonyms||[])],note:safe.note||''};
}
function node(tag,cls,text){const e=document.createElement(tag);if(cls)e.className=cls;if(text!==undefined)e.textContent=text;return e}
function render(card){
 const data=get(card),section=node('section','word-relations');
 section.setAttribute('aria-label','Sinónimos y antónimos de '+card.en);
 section.append(node('h4','','↔ Sinónimos y antónimos'));
 const list=node('dl','relations-list');
 function group(label,words,empty){
  list.append(node('dt','',label));const value=node('dd');
  if(!words.length)value.append(node('span','relation-empty',empty));
  else {const chips=node('ul','relation-chips');for(const word of words){const li=node('li','relation-chip',word);li.lang='en';chips.append(li)}value.append(chips)}
  list.append(value);
 }
 group('Sinónimos / equivalentes cercanos',data.synonyms,'Sin equivalente directo seleccionado para este sentido.');
 group('Antónimos',data.antonyms,'Sin antónimo habitual seleccionado para este sentido.');
 section.append(list);
 if(data.note)section.append(node('p','relation-note',data.note));
 if(data.synonyms.length||data.antonyms.length)section.append(node('p','relation-help','El significado y la estructura pueden cambiar según el contexto; no siempre se pueden intercambiar.'));
 return section;
}
window.WordRelations={get,render};

